/* Trade1 dashboard renderer. Reads data/markets.json (generated by scripts/collect.py).
   Every number shown is copied from the Kalshi API payload; blanks are flagged as unverified. */
(function () {
  "use strict";
  var page = document.body.getAttribute("data-page");
  var topic = document.body.getAttribute("data-topic");
  var root = document.getElementById("app");
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); };
  var has = function (v) { return v !== null && v !== undefined && v !== ""; };
  var px = function (v) { return has(v) ? "$" + Number(v).toFixed(2) : null; };
  var num = function (v) { return has(v) ? Number(v).toLocaleString("en-US", {maximumFractionDigits: 2}) : null; };
  var usd = function (v) { return has(v) ? "$" + Number(v).toLocaleString("en-US", {maximumFractionDigits: 0}) : null; };
  var when = function (ts) { return ts ? new Date(typeof ts === "number" ? ts * 1000 : ts).toISOString().replace("T", " ").slice(0, 16) + " UTC" : null; };
  // Cell: value, or a blank cell flagged as unverified when the source did not return it.
  var cell = function (v, fmt, cls) {
    var out = fmt ? fmt(v) : v;
    if (!has(out)) return '<td class="blank ' + (cls || "") + '"><span class="flag" title="Not returned by Kalshi API; flagged as unverified">&#9873; unverified</span></td>';
    return '<td class="' + (cls || "") + '">' + esc(out) + "</td>";
  };
  var srcLink = function (url) { return url ? '<a href="' + esc(url) + '" target="_blank" rel="noopener">API</a>' : '<span class="flag">no source</span>'; };
  // Resolve data relative to this script (trade1/assets/app.js -> trade1/data/), so subpages at any depth work.
  var scriptEl = document.currentScript || document.querySelector('script[src*="assets/app.js"]');
  var ROOT = new URL("../", scriptEl ? scriptEl.src : location.href);
  var fetchData = function () {
    return fetch(new URL("data/markets.json", ROOT), {cache: "no-store"}).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    });
  };
  var stamp = function (D) { return '<p class="note">Data as of ' + esc(when(D.generated_at) || "unknown") + ' · copied from <a href="https://docs.kalshi.com/welcome" target="_blank" rel="noopener">Kalshi public API</a> (open events only) · blanks are unverified</p>'; };

  // ---------- HOME
  function renderHome(D) {
    var topics = ["gas-prices", "elections", "culture", "crypto", "golf"];
    var totalRows = 0, jumps = D.jumps || [], resolved = D.resolved || [];
    topics.forEach(function (k) { totalRows += (D.topics[k] || {count: 0}).count; });
    var h = stamp(D) + '<div class="cards">' +
      card(totalRows, "open markets matched (all topics)") + card(jumps.length, "jumps ≥ $0.10 (last 7 days, hourly)") +
      card(resolved.length, "tracked markets resolved (yes/no)") + card((D.unverified || []).length, "items flagged unverified") + "</div>";
    h += "<h2>Topics</h2><div class='cards'>";
    topics.forEach(function (k) {
      var t = D.topics[k] || {label: k, count: 0};
      h += '<a class="card" style="text-decoration:none;color:inherit" href="' + k + '/"><b>' + esc(t.label) + '</b><span>' + t.count + ' open markets · view table →</span></a>';
    });
    h += "</div><h2>Highest estimated $ traded in 24h (top 10, all topics)</h2>";
    var all = [];
    topics.forEach(function (k) { (D.topics[k] ? D.topics[k].rows : []).forEach(function (r) { all.push(r); }); });
    all.sort(function (a, b) { return (b.est_dollars_24h || 0) - (a.est_dollars_24h || 0); });
    h += rowsTable(all.slice(0, 10), true);
    h += "<h2>Notes</h2><div class='panel'><ul>" +
      "<li>‘Est. $ 24h’ is calculated by this site as <i>volume_24h × last price</i> from Kalshi fields. It is an estimate, not a Kalshi-reported figure.</li>" +
      "<li>Topics come from the series category field where present; otherwise from keyword matches on market text (rule shown on each row).</li>" +
      "<li>Prices are in dollars per contract (a $1.00 contract pays $1 if YES). Refresh cadence is set by the GitHub Actions schedule.</li>" +
      "<li>Items that could not be confirmed are left blank and listed on the <a href='flagged/'>Flagged for Review</a> page.</li></ul></div>";
    root.innerHTML = h;
  }
  function card(n, label) { return '<div class="card"><b>' + esc(n) + "</b><span>" + esc(label) + "</span></div>"; }

  function rowsTable(rows, showTopic) {
    if (!rows.length) return '<div class="empty">No matching open markets in this snapshot.</div>';
    var h = '<div class="panel"><table><thead><tr>' +
      (showTopic ? "<th>Topic</th>" : "") +
      "<th>Event / market</th><th>Ticker</th><th class='n'>Yes bid</th><th class='n'>Yes ask</th><th class='n'>Last</th>" +
      "<th class='n'>Vol 24h (contracts)</th><th class='n'>Est. $ 24h</th><th class='n'>Open interest</th>" +
      "<th class='n'>Yes bid size</th><th class='n'>Yes ask size</th><th>Closes</th><th>Result</th><th>Match rule</th><th>Source</th></tr></thead><tbody>";
    var lastEvent = null;
    rows.forEach(function (r) {
      if (!showTopic && r.event_ticker !== lastEvent) {
        h += '<tr class="grp"><td colspan="15">' + esc(r.event_title || r.event_ticker) + " · <span class='note'>" + esc(r.event_ticker) + "</span></td></tr>";
        lastEvent = r.event_ticker;
      }
      h += "<tr>" + (showTopic ? "<td>" + esc((topicLabel(r.topic))) + "</td>" : "") +
        "<td>" + esc(r.market_title || "") + (r.outcome ? " <span class='pill'>" + esc(r.outcome) + "</span>" : "") + "</td>" +
        cell(r.ticker) + cell(r.yes_bid, px, "n") + cell(r.yes_ask, px, "n") + cell(r.last_price, px, "n") +
        cell(r.volume_24h, num, "n") + cell(r.est_dollars_24h, usd, "n") + cell(r.open_interest, num, "n") +
        cell(r.yes_bid_size, num, "n") + cell(r.yes_ask_size, num, "n") + cell(when(r.close_time)) +
        (r.result ? "<td class='" + (r.result === "yes" ? "yes" : "no") + "'>" + esc(r.result.toUpperCase()) + "</td>" : "<td><span class='note'>open (not settled)</span></td>") +
        cell(r.match_rule) + "<td>" + srcLink(r.source_url) + "</td></tr>";
    });
    return h + "</tbody></table></div>";
  }
  var LABELS = {"gas-prices": "Gas prices", elections: "Elections", culture: "Culture", crypto: "Crypto", golf: "Golf"};
  function topicLabel(k) { return LABELS[k] || k; }

  // ---------- TOPIC PAGE
  function renderTopic(D) {
    var t = D.topics[topic] || {label: topic, rows: [], count: 0};
    var rows = t.rows || [];
    var h = stamp(D) + "<h2>" + esc(LABELS[topic] || topic) + " — open markets (" + (t.count || rows.length) + ")</h2>" +
      (t.count > rows.length ? "<p class='note'>Showing the top " + rows.length + " by estimated 24h dollar volume out of " + t.count + ". The full list is in trade1/data/markets.json (rows per topic are capped to keep the page fast).</p>" : "") +
      "<p class='note'>Grouped by event. Yes bid/ask and last are dollars per $1 contract. Match rule shows how each market got into this topic.</p>" +
      rowsTable(rows, false);
    var tops = Object.keys(D.top_detail || {}).map(function (k) { return D.top_detail[k]; }).filter(function (d) { return d.topic === topic; });
    h += "<h2>Price chart, liquidity & order book</h2>";
    if (!tops.length) {
      h += '<div class="empty">No detailed markets yet for this topic.</div>';
    } else {
      h += '<div class="panel"><div class="ctrl"><label>Market <select id="mkt">' +
        tops.map(function (d) { var r = rows.find(function (x) { return x.ticker === d.ticker; }) || {};
          return '<option value="' + esc(d.ticker) + '">' + esc((r.market_title || d.ticker) + " — " + d.ticker) + "</option>"; }).join("") +
        '</select></label><span class="note">Range:</span><span id="ranges"></span></div>' +
        '<div id="gran" class="note"></div><svg id="chart" class="chart" viewBox="0 0 900 320" preserveAspectRatio="none"></svg>' +
        '<div class="grid2"><div><h3>Order book — YES bids and implied YES asks</h3><div id="book"></div></div>' +
        '<div><h3>Recent jumps ≥ $0.10 in this topic</h3><div id="jumps"></div></div></div></div>';
    }
    h += "<h2>Resolved (tracked until settlement)</h2><div id='res'></div>";
    root.innerHTML = h;
    renderResolved(D);
    if (tops.length) setupChart(D, tops);
    renderJumps(D);
  }

  function renderResolved(D) {
    var list = (D.resolved || []).filter(function (r) { return r.topic === topic; });
    var box = document.getElementById("res");
    if (!list.length) { box.innerHTML = '<div class="empty">No tracked market in this topic has resolved yet. Tracked markets are checked on every refresh until Kalshi reports result = yes or no.</div>'; return; }
    box.innerHTML = '<div class="panel"><table><thead><tr><th>Market</th><th>Ticker</th><th>Result</th><th>Status</th><th>Checked</th><th>Source</th></tr></thead><tbody>' +
      list.map(function (r) { return "<tr><td>" + esc(r.title || "") + "</td><td>" + esc(r.ticker) + '</td><td class="' + r.result + '">' + esc(r.result.toUpperCase()) + "</td><td>" + esc(r.status || "") + "</td><td>" + esc(when(r.checked_at) || "") + "</td><td>" + srcLink(r.source_url) + "</td></tr>"; }).join("") +
      "</tbody></table></div>";
  }

  function renderJumps(D) {
    var box = document.getElementById("jumps");
    if (!box) return;
    var list = (D.jumps || []).filter(function (j) { return j.topic === topic; });
    if (!list.length) { box.innerHTML = '<div class="empty">No hourly move ≥ $0.10 in the last 7 days for tracked markets in this topic.</div>'; return; }
    box.innerHTML = '<table><thead><tr><th>When (UTC)</th><th>Market</th><th class="n">Move</th><th>Cause</th></tr></thead><tbody>' +
      list.slice(0, 15).map(function (j) {
        return "<tr><td>" + esc(when(j.to_ts)) + "</td><td>" + esc(j.title || j.ticker) + '</td><td class="n ' + (j.delta > 0 ? "yes" : "no") + '">' + (j.delta > 0 ? "+" : "") + Number(j.delta).toFixed(2) + '</td><td class="unv">' + esc(j.cause_status) + " " + srcLink(j.source_url) + "</td></tr>";
      }).join("") + "</tbody></table>";
  }

  function setupChart(D, tops) {
    var sel = document.getElementById("mkt"), svg = document.getElementById("chart");
    var ranges = [["1h", 3600, "1m"], ["6h", 6 * 3600, "1m"], ["24h", 86400, "1m"], ["7d", 7 * 86400, "1h"]];
    var cur = {range: "24h"};
    var rbox = document.getElementById("ranges");
    rbox.innerHTML = ranges.map(function (r) { return '<button data-r="' + r[0] + '">' + r[0] + "</button>"; }).join(" ");
    function draw() {
      var d = D.top_detail[sel.value] || {};
      var rr = ranges.filter(function (r) { return r[0] === cur.range; })[0];
      var series = rr[2] === "1m" && d.candles_1m ? d.candles_1m : (d.candles_1h || []);
      var gran = rr[2] === "1m" && d.candles_1m ? "1-minute candles (Kalshi)" : "1-hour candles (Kalshi)";
      if (rr[2] === "1m" && !d.candles_1m) gran = "1-hour candles (1-minute not collected for this market)";
      document.getElementById("gran").textContent = "Granularity: " + gran + ". Seconds are not provided by this REST source.";
      var now = Math.floor(Date.now() / 1000);
      var pts = series.filter(function (c) { return c.p !== null && c.t >= now - rr[1]; });
      Array.prototype.forEach.call(rbox.querySelectorAll("button"), function (b) { b.className = b.getAttribute("data-r") === cur.range ? "on" : ""; });
      drawSVG(svg, pts, now - rr[1], now);
      document.getElementById("book").innerHTML = bookHTML(d);
    }
    sel.addEventListener("change", draw);
    rbox.addEventListener("click", function (e) { if (e.target.tagName === "BUTTON") { cur.range = e.target.getAttribute("data-r"); draw(); } });
    draw();
  }

  function drawSVG(svg, pts, t0, t1) {
    var W = 900, H = 320, L = 56, R = 16, T = 12, B = 34;
    if (!pts.length) { svg.innerHTML = '<text x="20" y="40" fill="#667085">No price points returned for this range (market may have had no trades).</text>'; return; }
    var lo = Math.min.apply(null, pts.map(function (p) { return p.p; })), hi = Math.max.apply(null, pts.map(function (p) { return p.p; }));
    if (hi - lo < 0.05) { var m = (hi + lo) / 2; lo = Math.max(0, m - 0.03); hi = Math.min(1, m + 0.03); }
    var x = function (t) { return L + (t - t0) / Math.max(1, t1 - t0) * (W - L - R); };
    var y = function (p) { return T + (1 - (p - lo) / Math.max(1e-9, hi - lo)) * (H - T - B); };
    var s = "";
    for (var i = 0; i <= 4; i++) {
      var v = lo + (hi - lo) * i / 4, yy = y(v);
      s += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + yy + '" y2="' + yy + '" stroke="#e4e7ec"/>';
      s += '<text x="' + (L - 6) + '" y="' + (yy + 4) + '" text-anchor="end" font-size="11" fill="#667085">$' + v.toFixed(2) + "</text>";
    }
    for (var j = 0; j <= 4; j++) {
      var tt = t0 + (t1 - t0) * j / 4, d = new Date(tt * 1000);
      var lab = (t1 - t0) > 86400 ? d.toISOString().slice(5, 16).replace("T", " ") : d.toISOString().slice(11, 16);
      s += '<text x="' + x(tt) + '" y="' + (H - 10) + '" text-anchor="middle" font-size="11" fill="#667085">' + lab + "</text>";
    }
    s += '<text x="12" y="' + (H / 2) + '" font-size="11" fill="#667085" transform="rotate(-90 12 ' + (H / 2) + ')" text-anchor="middle">YES price ($)</text>';
    s += '<text x="' + (W / 2) + '" y="' + (H - 0) + '" font-size="11" fill="#667085" text-anchor="middle">time (UTC)</text>';
    var path = pts.map(function (p, k) { return (k ? "L" : "M") + x(p.t).toFixed(1) + " " + y(p.p).toFixed(1); }).join(" ");
    s += '<path d="' + path + '" fill="none" stroke="#1d4ed8" stroke-width="2"/>';
    pts.forEach(function (p) {
      var jump = 0;
      s += '<circle cx="' + x(p.t).toFixed(1) + '" cy="' + y(p.p).toFixed(1) + '" r="2.2" fill="#1d4ed8"><title>' + esc(when(p.t)) + " · $" + p.p.toFixed(2) + "</title></circle>";
    });
    svg.innerHTML = s;
  }

  function bookHTML(d) {
    if (!d.orderbook) return '<div class="empty">Order book not collected for this market' + (d.orderbook_error ? " (" + esc(d.orderbook_error) + ")" : "") + ".</div>";
    var yes = d.orderbook.yes_bids.slice().reverse(), no = d.orderbook.no_bids.slice().reverse();
    var h = '<table><thead><tr><th>Price (YES)</th><th class="n">Contracts</th><th>Side</th></tr></thead><tbody>';
    yes.forEach(function (l) { h += '<tr><td>$' + esc(Number(l.price).toFixed(2)) + '</td><td class="n">' + esc(num(l.contracts)) + "</td><td>YES bid</td></tr>"; });
    no.forEach(function (l) {
      var askPx = (1 - Number(l.price)).toFixed(2);
      h += '<tr><td>$' + esc(askPx) + '</td><td class="n">' + esc(num(l.contracts)) + "</td><td>YES ask (= 1 − NO bid $" + esc(Number(l.price).toFixed(2)) + ")</td></tr>";
    });
    h += "</tbody></table><p class='note'>Source: " + srcLinkInline(d.orderbook.source_url) + ". Snapshot quantities are not guaranteed fills.</p>";
    return h;
  }
  function srcLinkInline(u) { return u ? '<a href="' + esc(u) + '" target="_blank" rel="noopener">Kalshi orderbook API</a>' : "unverified"; }

  // ---------- JUMPS (all topics)
  function renderJumpsPage(D) {
    var list = D.jumps || [];
    root.innerHTML = stamp(D) + "<h2>Sharp price jumps (≥ $0.10 between hourly closes, last 7 days)</h2>" +
      "<p class='note'>Cause fields are left blank: no official source is linked automatically. Add verified sources on the Flagged page.</p>" +
      (list.length ? '<div class="panel"><table><thead><tr><th>Topic</th><th>When (UTC)</th><th>Market</th><th class="n">From</th><th class="n">To</th><th class="n">Move</th><th>Cause</th><th>Source</th></tr></thead><tbody>' +
        list.map(function (j) { return "<tr><td>" + esc(topicLabel(j.topic)) + "</td><td>" + esc(when(j.to_ts)) + "</td><td>" + esc(j.title || j.ticker) + '</td><td class="n">$' + Number(j.from_price).toFixed(2) + '</td><td class="n">$' + Number(j.to_price).toFixed(2) + '</td><td class="n ' + (j.delta > 0 ? "yes" : "no") + '">' + (j.delta > 0 ? "+" : "") + Number(j.delta).toFixed(2) + '</td><td class="unv">' + esc(j.cause_status) + "</td><td>" + srcLink(j.source_url) + "</td></tr>"; }).join("") +
        "</tbody></table></div>" : '<div class="empty">No hourly move of $0.10 or more in the last 7 days for tracked markets.</div>');
    var res = D.resolved || [];
    root.innerHTML += "<h2>Resolved markets (yes / no)</h2>" + (res.length ? '<div class="panel"><table><thead><tr><th>Topic</th><th>Market</th><th>Ticker</th><th>Result</th><th>Source</th></tr></thead><tbody>' + res.map(function (r) { return "<tr><td>" + esc(topicLabel(r.topic)) + "</td><td>" + esc(r.title || "") + "</td><td>" + esc(r.ticker) + '</td><td class="' + r.result + '">' + esc(r.result.toUpperCase()) + "</td><td>" + srcLink(r.resolved_source) + "</td></tr>"; }).join("") + "</tbody></table></div>" : '<div class="empty">None yet. Tracked markets are re-checked every refresh.</div>');
    root.innerHTML += "<h2>Currently tracked (not yet resolved)</h2>" + trackingTable(D);
  }
  function trackingTable(D) {
    var t = D.tracking || [];
    if (!t.length) return '<div class="empty">Nothing tracked yet.</div>';
    return '<div class="panel"><table><thead><tr><th>Topic</th><th>Market</th><th>Ticker</th><th>Status</th><th>First seen</th><th>Checked</th><th>Source</th></tr></thead><tbody>' +
      t.map(function (r) { return "<tr><td>" + esc(topicLabel(r.topic)) + "</td><td>" + esc(r.title || "") + "</td><td>" + esc(r.ticker) + "</td>" + cell(r.status) + cell(when(r.first_seen)) + cell(when(r.checked_at)) + "<td>" + srcLink(r.source_url) + "</td></tr>"; }).join("") + "</tbody></table></div>";
  }

  // ---------- FLAGGED
  function renderFlagged(D, flags) {
    var h = stamp(D) + "<h2>Flagged for Review</h2><p class='note'>Irregularities found in the repository review and items that could not be verified. Nothing here was filled in or inferred. Each item links to its source for manual review.</p>";
    h += "<h3>A. Repository review findings (hand-recorded, see COORDINATION.md)</h3><div class='panel'><table><thead><tr><th>#</th><th>Finding</th><th>Evidence / source</th></tr></thead><tbody>" +
      (flags.repo || []).map(function (f, i) { return "<tr><td>" + (i + 1) + "</td><td>" + esc(f.finding) + "</td><td>" + (f.links || []).map(function (l) { return '<a href="' + esc(l[1]) + '" target="_blank" rel="noopener">' + esc(l[0]) + "</a>"; }).join("<br>") + "</td></tr>"; }).join("") +
      "</tbody></table></div>";
    var u = D.unverified || [];
    h += "<h3>B. Unverified / missing items from the latest collection run (" + u.length + ")</h3>";
    h += u.length ? '<div class="panel"><table><thead><tr><th>Type</th><th>Topic</th><th>Ticker</th><th>Detail</th><th>Source</th></tr></thead><tbody>' +
      u.slice(0, 500).map(function (x) { return "<tr><td>" + esc(x.type) + "</td><td>" + esc(topicLabel(x.topic || "")) + "</td><td>" + esc(x.ticker || "") + "</td><td>" + esc((x.fields || []).join(", ") || (x.type === "jump_without_cause" ? "no official cause source linked" : "")) + "</td><td>" + srcLink(x.source_url) + "</td></tr>"; }).join("") + "</tbody></table></div>" : '<div class="empty">No unverified items in the latest run.</div>';
    h += "<h3>C. Methodology notes to review</h3><div class='panel'><ul>" + (flags.method || []).map(function (m) { return "<li>" + esc(m) + "</li>"; }).join("") + "</ul></div>";
    root.innerHTML = h;
  }

  var loadFlags = fetch(new URL("data/flags.json", ROOT), {cache: "no-store"}).then(function (r) { return r.json(); }).catch(function () { return {}; });
  fetchData().then(function (D) {
    if (page === "home") renderHome(D);
    else if (page === "topic") renderTopic(D);
    else if (page === "jumps") renderJumpsPage(D);
    else if (page === "flagged") loadFlags.then(function (f) { renderFlagged(D, f); });
  }).catch(function (err) {
    root.innerHTML = '<div class="empty">Data not available yet (' + esc(err.message) + '). The first collection run populates this page.</div>';
  });
})();
